class Solution:
    def maxSplitScore(self, nums: list[int]) -> int:
        total_sum = sum(nums)
        left_sum = 0
        max_score = float('-inf')

        for i in range(len(nums) - 1):
            left_sum += nums[i]
            right_sum = total_sum - left_sum
            max_score = max(max_score, left_sum - right_sum)

        return max_score

